  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexandre Blais",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made the strong, controllable interaction of single artificial atoms and microwave photons a practical physical regime, with profound consequences for quantum optics and quantum information.",
        "attribution": "Blais and Girvin provided decisive theoretical architecture, while Schoelkopf established its experimental power; Andreas Wallraff is also central to the experimental realization.",
        "maturity": "The phenomena and platform have been reproduced and extended broadly over two decades, making the discovery fully mature.",
        "uncertainties": [
          "The conceptual and experimental credit is unusually distributed, and a three-person award cannot represent all central contributors.",
          "Its boundary relative to the 2025 prize for superconducting circuits would require especially careful definition."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their theoretical blueprint for trapped-ion quantum computing and quantum simulation transformed controllable atomic systems into a general laboratory for quantum many-body physics.",
        "attribution": "Cirac and Zoller are the clear joint originators of the influential foundational proposals.",
        "maturity": "The underlying ideas have been realized in many laboratories and now underpin a substantial experimental field.",
        "uncertainties": [
          "The achievement is principally theoretical and overlaps conceptually with broader quantum-information contributions."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Mikhail D. Lukin",
        "Antoine Browaeys",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade created a strikingly clean route to programmable, strongly interacting quantum systems and opened a new experimental regime for quantum simulation.",
        "attribution": "Saffman's theoretical work and the Lukin and Browaeys experimental programmes are central, though Grangier also made important foundational contributions.",
        "maturity": "Large, coherent neutral-atom arrays and blockade-mediated operations are now robustly demonstrated across laboratories.",
        "uncertainties": [
          "The most appropriate division between early blockade physics and later programmable-array development needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Peter W. Shor",
        "Alexei Kitaev",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the essential physical logic by which fragile quantum states can in principle support reliable computation, a fundamental conceptual breakthrough.",
        "attribution": "Shor, Kitaev, and Steane each made distinct foundational contributions to codes and fault-tolerant architectures.",
        "maturity": "Core principles are experimentally established and early logical demonstrations are compelling, although full-scale fault tolerance remains ahead.",
        "uncertainties": [
          "Whether present experimental realization is sufficiently mature for a prize centered on fault-tolerant computation remains uncertain.",
          "Many further contributors were indispensable to the broader field."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael Berry"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase revealed that phase and gauge structure have directly observable physical consequences, reshaping modern quantum physics.",
        "attribution": "Aharonov is directly identified with the first effect and Berry with the latter; both contributions have distinct, exceptional conceptual clarity.",
        "maturity": "Both effects are long-established experimentally and have become standard tools across quantum physics.",
        "uncertainties": [
          "The two discoveries are related through phase and topology but are historically distinct, making their treatment as one prize question less straightforward."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks achieved an extraordinary synthesis of quantum control and precision measurement, creating clocks of unprecedented accuracy and scientific reach.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept, while Ye made defining experimental advances and expanded its precision frontier.",
        "maturity": "Independent implementations have reached exceptional reproducibility and support demanding tests and measurements.",
        "uncertainties": [
          "The precise balance of conceptual origin and subsequent experimental development requires careful attribution."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution turned quantum measurement and entanglement into an operationally new form of secure communication, helping establish quantum information as a physical discipline.",
        "attribution": "Bennett and Brassard introduced the foundational protocol, and Ekert gave the entanglement-based formulation of comparable conceptual importance.",
        "maturity": "The central protocols are repeatedly demonstrated and deployed, with their physical principles firmly established.",
        "uncertainties": [
          "Practical security depends on implementation details beyond the ideal protocols.",
          "The intellectual territory substantially overlaps with other foundational quantum-information achievements."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Mark A. Kasevich",
        "Christian J. Bordé",
        "David E. Pritchard"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made matter-wave coherence into a precise and versatile measurement instrument, enabling major advances in inertial sensing and tests of fundamental physics.",
        "attribution": "Bordé, Pritchard, and Kasevich made major complementary theoretical and experimental contributions to its emergence.",
        "maturity": "The methods are well established, widely replicated, and continue to set precision benchmarks.",
        "uncertainties": [
          "The field has many foundational contributors, so limiting recognition to three names is difficult.",
          "Its most decisive scientific discovery is less sharply bounded than for some higher-ranked candidates."
        ]
      }
    }
  ]
}
